SET content_kk = '{"pages":[{"kicker":"Анықтама","title":"Әр мүше алдыңғысынан $d$-ға артық","blocks":[{"type":"formula","tex":"a_{n+1} = a_n + d \\qquad a_n = a_1 + (n - 1)d"},{"type":"list","items":["$d$ — айырым. $d > 0$ — өспелі, $d < 0$ — кемімелі.","$2, 5, 8, 11, \\ldots$: $a_1 = 2$, $d = 3$, $a_{20} = 2 + 19 \\cdot 3 = 59$."]}]},{"kicker":"Қосынды","title":"Алғашқы $n$ мүшенің қосындысы","blocks":[{"type":"formula","tex":"S_n = \\frac{a_1 + a_n}{2} \\cdot n = \\frac{2a_1 + (n - 1)d}{2} \\cdot n"},{"type":"list","items":["$1 + 2 + \\ldots + 100 = \\frac{1 + 100}{2} \\cdot 100 = 5050$.","Соңғы мүше белгілі болса — бірінші формула, айырым белгілі болса — екінші."]}]},{"kicker":"Қасиеттері","title":"Ортаңғы мүше және симметрия","blocks":[{"type":"formula","tex":"a_n = \\frac{a_{n-1} + a_{n+1}}{2} \\qquad a_k + a_m = a_p + a_q,\\ k + m = p + q"},{"type":"list","items":["$a_3 + a_9 = a_5 + a_7 = 2a_6$.","$2y = x + z$ болса, $x, y, z$ сандары прогрессия құрайды."]}]},{"kicker":"Екі мүше","title":"$a_1$ мен $d$-ны табу","blocks":[{"type":"text","text":"$a_m$ мен $a_k$ берілсе: $d = \\frac{a_k - a_m}{k - m}$, содан кейін $a_1 = a_m - (m - 1)d$."},{"type":"note","text":"$a_4 = 10$, $a_9 = 25$: $d = \\frac{15}{5} = 3$, $a_1 = 10 - 9 = 1$."}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["$a_n$ формуласында $n$ емес, $(n - 1)$ көбейткіші.","$a_k$-дан $a_m$-ға дейінгі (қоса алғанда) мүшелер саны: $m - k + 1$.","5-ші мүшеден 10-шы мүшеге дейінгі мүшелердің қосындысы: $S_{10} - S_5$ емес, $S_{10} - S_4$.","Мүше нөмірі — натурал сан: бөлшек шықса, мұндай мүше жоқ."]}]}]}'::jsonb
