UPDATE public.books
SET content_kk = '{"pages":[{"kicker":"Анықтама","title":"Түбір дегеніміз не","blocks":[{"type":"text","text":"$a$ санының **квадрат түбірі** — квадраты $a$-ға тең сан. **Арифметикалық** түбір $\\sqrt{a}$ — олардың теріс емесі."},{"type":"formula","tex":"\\sqrt{a} = b \\iff b \\ge 0,\\ b^2 = a"},{"type":"list","items":["$\\sqrt{a}$ тек $a \\ge 0$ болғанда анықталған.","$\\sqrt{49} = 7$, $\\pm 7$ емес. $\\pm$ таңбасы $x^2 = 49$ теңдеуін шешкенде пайда болады.","$n$-дәрежелі түбір: $\\sqrt[n]{a} = b \\iff b^n = a$. Жұп $n$ үшін $a \\ge 0$ және $b \\ge 0$ болуы керек, тақ $n$ үшін кез келген $a$: $\\sqrt[3]{-8} = -2$."]}]},{"kicker":"Басты қақпан","title":"Квадраттан алынған түбір","blocks":[{"type":"formula","tex":"\\sqrt{a^2} = |a|"},{"type":"list","items":["$\\sqrt{(-5)^2} = |-5| = 5$.","$\\sqrt{(2 - \\sqrt{5})^2} = |2 - \\sqrt{5}| = \\sqrt{5} - 2$, себебі $\\sqrt{5} > 2$.","Тақ дәреже үшін модуль керек емес: $\\sqrt[3]{a^3} = a$."]},{"type":"note","text":"Квадраттан түбірді алмас бұрын квадраттың ішіндегі өрнектің таңбасын анықта."}]},{"kicker":"Қасиеттері","title":"Түбірлермен қалай жұмыс істеу керек","blocks":[{"type":"formula","tex":"\\sqrt{ab} = \\sqrt{a}\\sqrt{b} \\qquad \\sqrt{\\frac{a}{b}} = \\frac{\\sqrt{a}}{\\sqrt{b}} \\qquad (\\sqrt{a})^2 = a"},{"type":"list","items":["Қасиеттер $a \\ge 0$, $b \\ge 0$ болғанда орындалады (бөлшекте $b > 0$).","$\\sqrt{2} \\cdot \\sqrt{18} = \\sqrt{36} = 6$.","$\\frac{\\sqrt{75}}{\\sqrt{3}} = \\sqrt{25} = 5$.","Қосындыдан түбір бөлек алынбайды: $\\sqrt{9 + 16} = 5$, ал $\\sqrt{9} + \\sqrt{16} = 7$."]}]},{"kicker":"Тәсіл","title":"Көбейткішті түбір астынан шығару","blocks":[{"type":"text","text":"Түбір астындағы санды бір көбейткіші толық квадрат болатындай жікте."},{"type":"list","items":["$\\sqrt{50} = \\sqrt{25 \\cdot 2} = 5\\sqrt{2}$.","$\\sqrt{72} = \\sqrt{36 \\cdot 2} = 6\\sqrt{2}$.","Кері амал — көбейткішті түбір астына енгізу: $3\\sqrt{2} = \\sqrt{9 \\cdot 2} = \\sqrt{18}$. Түбірлерді салыстыруға ыңғайлы."]},{"type":"note","text":"$2\\sqrt{7}$ мен $3\\sqrt{3}$-ті салыстыр: $\\sqrt{28}$ және $\\sqrt{27}$, демек $2\\sqrt{7}$ үлкен."}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["$\\sqrt{a^2} = a$ — $a < 0$ болғанда қате. Дұрысы: $|a|$.","$\\sqrt{a + b} \\ne \\sqrt{a} + \\sqrt{b}$.","$\\sqrt{0{,}09} = 0{,}3$, $0{,}03$ емес.","Жұп дәрежелі түбір астындағы теріс сан — өрнектің мағынасы жоқ."]}]}]}'::jsonb
