UPDATE public.books
SET content_kk = '{"pages":[{"kicker":"Сипаттамалары","title":"Период, жиілік, бұрыштық жылдамдық","blocks":[{"type":"formula","tex":"T = \\frac{t}{N} \\qquad \\nu = \\frac{1}{T} \\qquad \\omega = \\frac{2\\pi}{T} = 2\\pi\\nu"},{"type":"list","items":["$T$ — бір айналым уақыты, с.","$\\nu$ — секундтағы айналымдар саны, Гц (айн/с).","$\\omega$ — секундтағы бұрылу бұрышы, рад/с."]}]},{"kicker":"Жылдамдық","title":"Сызықтық жылдамдық","blocks":[{"type":"formula","tex":"v = \\frac{2\\pi R}{T} = \\omega R"},{"type":"list","items":["Шеңберге жанама бойымен бағытталған.","Айналатын дискінің барлық нүктелерінде $\\omega$ бірдей, ал $v$ әртүрлі: центрден алыс — жылдамырақ.","Белдікті берілістің нүктелерінде және ілініскен дөңгелектердің шеттерінде $v$ бірдей."]}]},{"kicker":"Үдеу","title":"Центрге тартқыш үдеу","blocks":[{"type":"formula","tex":"a = \\frac{v^2}{R} = \\omega^2 R"},{"type":"list","items":["Шеңбердің центріне бағытталған.","Жылдамдық модулі тұрақты, бірақ бағыты өзгереді — сондықтан үдеу бар.","Жылдамдықты 2 есе арттырса — үдеу 4 есе артады."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Шеңбер бойымен бірқалыпты қозғалыс — **үдеумен** қозғалыс.","айн/мин-ты Гц-ке 60-қа бөліп аударады.","Үдеу жылдамдыққа емес, оның квадратына пропорционал.","Бір осьте $\\omega$ мен $T$ бірдей; бір белдікте $v$ бірдей."]}]}]}'::jsonb
WHERE slug = 'circular-motion' AND content_kk = '{"pages":[{"kicker":"Сипаттамалары","title":"Период, жиілік, бұрыштық жылдамдық","blocks":[{"type":"formula","tex":"T = \\frac{t}{N} \\qquad \\nu = \\frac{1}{T} \\qquad \\omega = \\frac{2\\pi}{T} = 2\\pi\\nu"},{"type":"list","items":["$T$ — бір айналым уақыты, с.","$\\nu$ — секундтағы айналымдар саны, Гц (айн/с).","$\\omega$ — секундтағы бұрылу бұрышы, рад/с."]}]},{"kicker":"Жылдамдық","title":"Сызықтық жылдамдық","blocks":[{"type":"formula","tex":"v = \\frac{2\\pi R}{T} = \\omega R"},{"type":"list","items":["Шеңберге жанама бойымен бағытталған.","Айналатын дискінің барлық нүктелерінде $\\omega$ бірдей, ал $v$ әртүрлі: центрден алыс — жылдамырақ.","Белдікті беріліс нүктелері мен ілініскен дөңгелектердің шеттерінде $v$ бірдей."]}]},{"kicker":"Үдеу","title":"Центрге тартқыш үдеу","blocks":[{"type":"formula","tex":"a = \\frac{v^2}{R} = \\omega^2 R"},{"type":"list","items":["Шеңбердің центріне бағытталған.","Жылдамдық модулі тұрақты, бірақ бағыты өзгереді — сондықтан үдеу бар.","Жылдамдықты 2 есе арттырса — үдеу 4 есе артады."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Шеңбер бойымен бірқалыпты қозғалыс — **үдеумен** қозғалыс.","айн/мин-ты Гц-ке 60-қа бөліп аударады.","Үдеу жылдамдыққа емес, оның квадратына пропорционал.","Бір осьте $\\omega$ мен $T$ бірдей; бір белдікте $v$ бірдей."]}]}]}'::jsonb;

UPDATE public.books
SET content_kk = '{"pages":[{"kicker":"Энергия түрлері","title":"Кинетикалық және потенциалдық","blocks":[{"type":"formula","tex":"E_k = \\frac{mv^2}{2} \\qquad E_p = mgh \\qquad E_p = \\frac{kx^2}{2}"},{"type":"list","items":["$E_k$ — қозғалыс энергиясы, әрқашан $\\ge 0$.","$E_p = mgh$ — нөлдік деңгейді таңдауға тәуелді.","$E_p = \\frac{kx^2}{2}$ — деформацияланған серіппенің энергиясы."]}]},{"kicker":"Сақталу заңы","title":"Толық механикалық энергия","blocks":[{"type":"formula","tex":"E_k + E_p = \\text{const}"},{"type":"list","items":["Үйкеліс пен кедергі болмаса орындалады.","Дене $h$ биіктіктен түседі: $mgh = \\frac{mv^2}{2}$, $v = \\sqrt{2gh}$ — масса қысқарады.","Маятник: төменгі нүктеде $E_k$ максимум, шеткі нүктелерде $E_p$ максимум."]}]},{"kicker":"Үйкеліспен","title":"Энергия жылуға айналады","blocks":[{"type":"formula","tex":"E_{\\text{бас}} = E_{\\text{соң}} + |A_{\\text{үйк}}|"},{"type":"list","items":["Толық механикалық энергияны тек үйкеліс өзгертсе, энергияның өзгерісі үйкеліс жұмысына тең.","Бөлінген жылу $Q = |A_{\\text{үйк}}|$."]},{"type":"note","text":"2 кг білеуше 5 м биіктіктен сырғанап, төменде 8 м/с жылдамдыққа ие болды: $|A_{\\text{үйк}}| = 100 - 64 = 36$ Дж."}]},{"kicker":"Теорема","title":"Кинетикалық энергия туралы теорема","blocks":[{"type":"formula","tex":"A_{\\text{бар. күш}} = E_{k2} - E_{k1}"},{"type":"list","items":["Тең әсерлі күштің жұмысы кинетикалық энергияның өзгерісіне тең.","Тежелу жолы: $\\mu mgs = \\frac{mv^2}{2}$ → $s = \\frac{v^2}{2\\mu g}$. Жылдамдық 2 есе үлкен — жол 4 есе үлкен."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Серпімсіз соқтығысуда механикалық энергияның сақталу заңын қолданады.","Жылдамдықты 2 есе арттырса — $E_k$ 2 есе емес, 4 есе артады.","Горизонтқа бұрыш жасай лақтырудың жоғарғы нүктесінде $E_k \\ne 0$: горизонталь жылдамдық қалады.","Биіктікті көлбеу жазықтықтың ұзындығымен шатастырады."]}]}]}'::jsonb
WHERE slug = 'energy-conservation' AND content_kk = '{"pages":[{"kicker":"Энергия түрлері","title":"Кинетикалық және потенциалдық","blocks":[{"type":"formula","tex":"E_k = \\frac{mv^2}{2} \\qquad E_p = mgh \\qquad E_p = \\frac{kx^2}{2}"},{"type":"list","items":["$E_k$ — қозғалыс энергиясы, әрқашан $\\ge 0$.","$E_p = mgh$ — нөлдік деңгейді таңдауға тәуелді.","$E_p = \\frac{kx^2}{2}$ — деформацияланған серіппенің энергиясы."]}]},{"kicker":"Сақталу заңы","title":"Толық механикалық энергия","blocks":[{"type":"formula","tex":"E_k + E_p = \\text{const}"},{"type":"list","items":["Үйкеліс пен кедергі болмаса орындалады.","Дене $h$ биіктіктен түседі: $mgh = \\frac{mv^2}{2}$, $v = \\sqrt{2gh}$ — масса қысқарады.","Маятник: төменгі нүктеде $E_k$ максимум, шеткі нүктелерде $E_p$ максимум."]}]},{"kicker":"Үйкеліспен","title":"Энергия жылуға айналады","blocks":[{"type":"formula","tex":"E_{\\text{бас}} = E_{\\text{соң}} + |A_{\\text{үйк}}|"},{"type":"list","items":["Толық механикалық энергияны тек үйкеліс өзгертсе, энергияның өзгерісі үйкеліс жұмысына тең.","Бөлінген жылу $Q = |A_{\\text{үйк}}|$."]},{"type":"note","text":"2 кг білеуше 5 м биіктіктен сырғанап, төменде 8 м/с жылдамдыққа ие: $|A_{\\text{үйк}}| = 100 - 64 = 36$ Дж."}]},{"kicker":"Теорема","title":"Кинетикалық энергия туралы теорема","blocks":[{"type":"formula","tex":"A_{\\text{бар. күш}} = E_{k2} - E_{k1}"},{"type":"list","items":["Тең әсерлі күштің жұмысы кинетикалық энергияның өзгерісіне тең.","Тежелу жолы: $\\mu mgs = \\frac{mv^2}{2}$ → $s = \\frac{v^2}{2\\mu g}$. Жылдамдық 2 есе үлкен — жол 4 есе үлкен."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Серпімсіз соқтығысуда механикалық энергияның сақталу заңын қолданады.","Жылдамдықты 2 есе арттырса — $E_k$ 2 есе емес, 4 есе артады.","Бұрышпен лақтырудың жоғарғы нүктесінде $E_k \\ne 0$: горизонталь жылдамдық қалады.","Биіктікті көлбеу жазықтықтың ұзындығымен шатастырады."]}]}]}'::jsonb;

UPDATE public.books
SET content_kk = '{"pages":[{"kicker":"Не үшін","title":"Жіктеу — көбейтінді түрінде жазу","blocks":[{"type":"text","text":"Көбейтінді ыңғайлы: оны қысқарту және нөлге теңестіру оңай. $ab = 0 \\iff a = 0$ немесе $b = 0$."},{"type":"list","items":["Ортақ көбейткішті жақша сыртына шығару.","Қысқаша көбейту формуласын қолдану.","Топтастыру.","Квадрат үшмүшені түбірлері арқылы жіктеу."],"ordered":true}]},{"kicker":"1-тәсіл","title":"Ортақ көбейткішті жақша сыртына шығару","blocks":[{"type":"list","items":["$6x^3 - 9x^2 = 3x^2(2x - 3)$.","$a(x - y) + b(y - x) = (x - y)(a - b)$ — екінші жақшада таңбаны ауыстырдық.","Ең үлкен ортақ көбейткішті шығар: санды да, айнымалының ең кіші дәрежесін де."]}]},{"kicker":"2-тәсіл","title":"Топтастыру","blocks":[{"type":"text","text":"Ортақ көбейткіші бар жұптарға бөл, содан кейін ортақ жақшаны шығар."},{"type":"list","items":["$ax + ay + 3x + 3y = a(x + y) + 3(x + y) = (x + y)(a + 3)$.","$x^3 - 2x^2 - 4x + 8 = x^2(x - 2) - 4(x - 2) = (x - 2)^2(x + 2)$."]}]},{"kicker":"3-тәсіл","title":"Квадрат үшмүше","blocks":[{"type":"formula","tex":"ax^2 + bx + c = a(x - x_1)(x - x_2)"},{"type":"list","items":["$x_1, x_2$ — $ax^2 + bx + c = 0$ теңдеуінің түбірлері.","$2x^2 - 7x + 3 = 2(x - 3)\\left(x - \\frac{1}{2}\\right) = (x - 3)(2x - 1)$.","$D < 0$ болса, үшмүше көбейткіштерге жіктелмейді."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["$a$ көбейткішін ұмытады: $2x^2 - 7x + 3 \\ne (x - 3)(x - 0{,}5)$.","Минусты шығарғанда жақшадағы **барлық** қосылғыштардың таңбасы өзгереді.","Көбейткіштерді қысқартуға болады, қосылғыштарды қысқартуға болмайды: $\\frac{x + 2}{x} \\ne 2$.","Жақшаларды ашып, жіктеудің дұрыстығын тексер."]}]}]}'::jsonb
WHERE slug = 'factoring' AND content_kk = '{"pages":[{"kicker":"Не үшін","title":"Жіктеу — көбейтінді түрінде жазу","blocks":[{"type":"text","text":"Көбейтінді ыңғайлы: оны қысқарту және нөлге теңестіру оңай. $ab = 0 \\iff a = 0$ немесе $b = 0$."},{"type":"list","items":["Ортақ көбейткішті жақша сыртына шығару.","Қысқаша көбейту формуласын қолдану.","Топтастыру.","Квадрат үшмүшені түбірлері арқылы жіктеу."],"ordered":true}]},{"kicker":"1-тәсіл","title":"Ортақ көбейткішті жақша сыртына шығару","blocks":[{"type":"list","items":["$6x^3 - 9x^2 = 3x^2(2x - 3)$.","$a(x - y) + b(y - x) = (x - y)(a - b)$ — екінші жақшада таңбаны ауыстырдық.","Ең үлкен ортақ көбейткішті шығар: санды да, айнымалының ең кіші дәрежесін де."]}]},{"kicker":"2-тәсіл","title":"Топтастыру","blocks":[{"type":"text","text":"Ортақ көбейткіші бар жұптарға бөл, содан кейін ортақ жақшаны шығар."},{"type":"list","items":["$ax + ay + 3x + 3y = a(x + y) + 3(x + y) = (x + y)(a + 3)$.","$x^3 - 2x^2 - 4x + 8 = x^2(x - 2) - 4(x - 2) = (x - 2)^2(x + 2)$."]}]},{"kicker":"3-тәсіл","title":"Квадрат үшмүше","blocks":[{"type":"formula","tex":"ax^2 + bx + c = a(x - x_1)(x - x_2)"},{"type":"list","items":["$x_1, x_2$ — $ax^2 + bx + c = 0$ теңдеуінің түбірлері.","$2x^2 - 7x + 3 = 2(x - 3)\\left(x - \\frac{1}{2}\\right) = (x - 3)(2x - 1)$.","$D < 0$ болса, үшмүше көбейткіштерге жіктелмейді."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["$a$ көбейткішін ұмытады: $2x^2 - 7x + 3 \\ne (x - 3)(x - 0{,}5)$.","Минусты шығарғанда жақшадағы **барлық** қосылғыштардың таңбасы өзгереді.","Көбейткіштерді қысқартуға болады, қосылғыштарды — жоқ: $\\frac{x + 2}{x} \\ne 2$.","Жіктеуді жақшаны кері ашу арқылы тексер."]}]}]}'::jsonb;

UPDATE public.books
SET content_kk = '{"pages":[{"kicker":"Ауырлық күші және салмақ","title":"Бұлар әртүрлі күштер","blocks":[{"type":"formula","tex":"F_{\\text{ауыр}} = mg \\qquad P = m(g \\pm a)"},{"type":"list","items":["**Ауырлық күші** денеге түсірілген, Жер тарапынан әсер етеді.","**Салмақ** тірекке немесе аспаға түсірілген.","Лифт жоғары үдеумен — салмақ $mg$-дан үлкен; төмен — кіші.","Еркін түсу — **салмақсыздық**: $P = 0$."]}]},{"kicker":"Серпімділік күші","title":"Гук заңы","blocks":[{"type":"formula","tex":"F_{\\text{серп}} = k|\\Delta x|"},{"type":"list","items":["$k$ — қатаңдық, Н/м. Заң серпімді (аз) деформациялар үшін орындалады.","Екі серіппе тізбектей: $\\frac{1}{k} = \\frac{1}{k_1} + \\frac{1}{k_2}$.","Параллель: $k = k_1 + k_2$.","Серіппені екіге қиса — жартысының қатаңдығы 2 есе артады."]}]},{"kicker":"Үйкеліс күші","title":"Сырғанау және тыныштық үйкелісі","blocks":[{"type":"formula","tex":"F_{\\text{үйк}} = \\mu N"},{"type":"list","items":["$\\mu$ — үйкеліс коэффициенті, өлшемсіз шама.","Горизонталь бетте $N = mg$; көлбеу бетте $N = mg\\cos\\alpha$.","Тыныштық үйкелісі 0-ден $\\mu N$-ге дейін өзгереді — дене қозғалғанға дейін түсірілген күшке тең.","Жанасу ауданына тәуелсіз."]}]},{"kicker":"Көлбеу жазықтық","title":"Ауырлық күшін жіктеу","blocks":[{"type":"list","items":["Көлбеу бойымен: $mg\\sin\\alpha$.","Көлбеуге перпендикуляр: $mg\\cos\\alpha$.","Дене үйкеліссіз сырғанаса: $a = g\\sin\\alpha$.","Үйкеліспен: $a = g(\\sin\\alpha - \\mu\\cos\\alpha)$. $\\mu \\ge \\tan\\alpha$ болса — дене тыныштықта қалады."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Салмақ пен ауырлық күші тек тыныштықта не бірқалыпты қозғалыста тең.","Көлбеу жазықтықта $N \\ne mg$.","Тыныштық үйкеліс күші әрқашан $\\mu N$-ге тең емес.","Салмақ килограммен емес, ньютонмен өлшенеді."]}]}]}'::jsonb
WHERE slug = 'forces-in-mechanics' AND content_kk = '{"pages":[{"kicker":"Ауырлық күші және салмақ","title":"Бұлар әртүрлі күштер","blocks":[{"type":"formula","tex":"F_{\\text{ауыр}} = mg \\qquad P = m(g \\pm a)"},{"type":"list","items":["**Ауырлық күші** денеге түсірілген, Жер тарапынан әсер етеді.","**Салмақ** тірекке немесе ілгішке түсірілген.","Лифт жоғары үдеумен — салмақ $mg$-дан үлкен; төмен — кіші.","Еркін түсу — **салмақсыздық**: $P = 0$."]}]},{"kicker":"Серпімділік күші","title":"Гук заңы","blocks":[{"type":"formula","tex":"F_{\\text{серп}} = k|\\Delta x|"},{"type":"list","items":["$k$ — қатаңдық, Н/м. Заң шағын деформациялар үшін орындалады.","Екі серіппе тізбектей: $\\frac{1}{k} = \\frac{1}{k_1} + \\frac{1}{k_2}$.","Параллель: $k = k_1 + k_2$.","Серіппені екіге қиса — жартысының қатаңдығы 2 есе артады."]}]},{"kicker":"Үйкеліс күші","title":"Сырғанау және тыныштық үйкелісі","blocks":[{"type":"formula","tex":"F_{\\text{үйк}} = \\mu N"},{"type":"list","items":["$\\mu$ — үйкеліс коэффициенті, бірліксіз.","Горизонталь бетте $N = mg$; көлбеу бетте $N = mg\\cos\\alpha$.","Тыныштық үйкелісі 0-ден $\\mu N$-ге дейін өзгереді — дене қозғалғанға дейін түсірілген күшке тең.","Жанасу ауданына тәуелсіз."]}]},{"kicker":"Көлбеу жазықтық","title":"Ауырлық күшін жіктеу","blocks":[{"type":"list","items":["Көлбеу бойымен: $mg\\sin\\alpha$.","Көлбеуге перпендикуляр: $mg\\cos\\alpha$.","Үйкеліссіз сырғанайды: $a = g\\sin\\alpha$.","Үйкеліспен: $a = g(\\sin\\alpha - \\mu\\cos\\alpha)$. $\\mu \\ge \\tan\\alpha$ болса — тыныштықта."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Салмақ пен ауырлық күші тек тыныштықта не бірқалыпты қозғалыста тең.","Көлбеу жазықтықта $N \\ne mg$.","Тыныштық үйкеліс күші әрқашан $\\mu N$-ге тең емес.","Салмақ килограммен емес, ньютонмен өлшенеді."]}]}]}'::jsonb;

UPDATE public.books
SET content_kk = '{"pages":[{"kicker":"Жай бөлшектер","title":"Қосу және азайту","blocks":[{"type":"text","text":"Бөлшектер тек **ортақ бөлімге келтірілгеннен кейін** қосылады. Ең кіші ортақ еселікті (ЕКОЕ) алған дұрыс."},{"type":"formula","tex":"\\frac{a}{b} + \\frac{c}{d} = \\frac{ad + cb}{bd}"},{"type":"list","items":["$\\frac{1}{4} + \\frac{1}{6} = \\frac{3}{12} + \\frac{2}{12} = \\frac{5}{12}$ (ЕКОЕ(4, 6) = 12).","Аралас санды бұрыс бөлшекке айналдыр: $2\\frac{1}{3} = \\frac{7}{3}$.","Жауапта бөлшекті соңына дейін қысқарт."]}]},{"kicker":"Жай бөлшектер","title":"Көбейту және бөлу","blocks":[{"type":"formula","tex":"\\frac{a}{b} \\cdot \\frac{c}{d} = \\frac{ac}{bd} \\qquad \\frac{a}{b} : \\frac{c}{d} = \\frac{a}{b} \\cdot \\frac{d}{c}"},{"type":"list","items":["Көбейтуден **бұрын** қысқарт: $\\frac{6}{35} \\cdot \\frac{14}{9} = \\frac{2 \\cdot 2}{5 \\cdot 3} = \\frac{4}{15}$.","Бөлшекке бөлу үшін оның кері бөлшегіне көбейт. Бөлімдер де, бөлгіш те нөлге тең болмауы керек.","Көпқабатты бөлшек: $\\frac{a/b}{c/d} = \\frac{ad}{bc}$."]}]},{"kicker":"Ондық бөлшектер","title":"Аудару және есептеу","blocks":[{"type":"list","items":["$0{,}25 = \\frac{1}{4}$, $0{,}5 = \\frac{1}{2}$, $0{,}2 = \\frac{1}{5}$, $0{,}125 = \\frac{1}{8}$, $0{,}75 = \\frac{3}{4}$ — жатқа біл.","Ондық бөлшектерді көбейткенде көбейткіштерде үтірден кейін барлығы неше цифр болса, нәтижеде оң жақтан сонша цифр санап, үтір қоямыз: $0{,}3 \\cdot 0{,}02 = 0{,}006$.","Ондық бөлшекке бөлгенде екі санда да үтірді жылжыт: $1{,}2 : 0{,}04 = 120 : 4 = 30$."]},{"type":"note","text":"Мысалда жай және ондық бөлшектер аралас болса, әдетте жай бөлшекке көшкен ыңғайлы."}]},{"kicker":"Амалдар реті","title":"Сандық өрнектер","blocks":[{"type":"list","items":["Жақша ішіндегі амалдар.","Дәрежелер мен түбірлер.","Көбейту мен бөлу — солдан оңға.","Қосу мен азайту — солдан оңға."],"ordered":true},{"type":"note","text":"Мысал: $2 - 3 \\cdot \\left(\\frac{1}{2}\\right)^2 = 2 - \\frac{3}{4} = 1\\frac{1}{4}$."}]},{"kicker":"Пайыздар","title":"Пайыз — жүзден бір бөлік","blocks":[{"type":"list","items":["$a$ санының $p\\%$-ы: $a \\cdot \\frac{p}{100}$.","Бөлігі бойынша санды табу: санның $p\\%$-ы $b$-ға тең болса, сан $= \\frac{100b}{p}$.","$p\\%$-ға арттыру — $1 + \\frac{p}{100}$-ге көбейту; кеміту — $1 - \\frac{p}{100}$-ге."]},{"type":"trap","items":["20%-ға өсу мен 20%-ға кему бастапқы мәнге қайтармайды: $1{,}2 \\cdot 0{,}8 = 0{,}96$.","Алымдарды алыммен, бөлімдерді бөліммен қосады: $\\frac{1}{2} + \\frac{1}{3} \\ne \\frac{2}{5}$.","Бөлгенде басқа бөлшекті аударады: бөлінгішті емес, бөлгішті аудару керек."]}]}]}'::jsonb
