UPDATE public.books
SET content_kk = '{"pages":[{"kicker":"Анықтама","title":"Бірқалыпты түзу сызықты қозғалыс","blocks":[{"type":"text","text":"Дене **кез келген тең** уақыт аралықтарында тең жолдар жүреді. Жылдамдық модулі де, бағыты да тұрақты."},{"type":"formula","tex":"x = x_0 + v_x t \\qquad s = vt"},{"type":"list","items":["$v_x > 0$ — ось бойымен, $v_x < 0$ — оське қарсы.","$x = 5 - 2t$: бастапқы координата 5 м, жылдамдық $-2$ м/с."]}]},{"kicker":"Графиктер","title":"Графиктерді қалай оқу керек","blocks":[{"type":"list","items":["$x(t)$ — түзу. Көлбеулігі = жылдамдық: $v = \\frac{\\Delta x}{\\Delta t}$.","$v(t)$ — горизонталь түзу.","$v(t)$ графигінің астындағы аудан = орын ауыстыру.","$x(t)$ графигі неғұрлым тік болса, жылдамдық соғұрлым үлкен."]},{"type":"note","text":"$x_1(t)$ мен $x_2(t)$ графиктерінің қиылысу нүктесі — кездесу орны мен уақыты."}]},{"kicker":"Кездесу","title":"Екі дененің қозғалысына есептер","blocks":[{"type":"list","items":["$x_1(t)$ мен $x_2(t)$-ны бір координаталар жүйесінде жаз.","Теңестір: $x_1(t) = x_2(t)$ — кездесу уақытын табасың.","Уақытты кез келген теңдеуге қой — орнын табасың."],"ordered":true},{"type":"note","text":"$x_1 = 2t$, $x_2 = 120 - 4t$: $2t = 120 - 4t$, $t = 20$ с, $x = 40$ м."}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Жылдамдық таңбасы: оське қарсы қозғалатын дененің $v_x < 0$.","Бір есепте әртүрлі бірліктер: км мен м, сағ пен с.","$v_x < 0$ болғанда да жол оң: $s = |v| t$.","Осьтердің масштабын тексермей, графиктің көлбеулігін тор көзімен оқиды."]}]}]}'::jsonb
