UPDATE public.books
SET content_kk = '{"pages":[{"kicker":"Теорема","title":"Виет теоремасы","blocks":[{"type":"formula","tex":"ax^2 + bx + c = 0:\\quad x_1 + x_2 = -\\frac{b}{a} \\qquad x_1 x_2 = \\frac{c}{a}"},{"type":"list","items":["Келтірілген $x^2 + px + q = 0$ үшін: $x_1 + x_2 = -p$, $x_1 x_2 = q$.","Тек түбірлер бар болғанда орындалады: алдымен $D \\ge 0$ шартын тексер."]}]},{"kicker":"Түбірлерді іріктеу","title":"Ауызша шешу","blocks":[{"type":"text","text":"Қосындысы мен көбейтіндісі берілген мәндерге тең екі сан іздейміз."},{"type":"list","items":["$x^2 - 7x + 12 = 0$: қосынды $7$, көбейтінді $12$ → $3$ және $4$.","$x^2 + 2x - 15 = 0$: қосынды $-2$, көбейтінді $-15$ → $3$ және $-5$.","Көбейтінді теріс — түбірлердің таңбалары әртүрлі."]}]},{"kicker":"Симметриялы өрнектер","title":"Түбірлерді таппай","blocks":[{"type":"formula","tex":"x_1^2 + x_2^2 = (x_1 + x_2)^2 - 2x_1x_2"},{"type":"formula","tex":"\\frac{1}{x_1} + \\frac{1}{x_2} = \\frac{x_1 + x_2}{x_1 x_2} \\qquad (x_1 - x_2)^2 = (x_1 + x_2)^2 - 4x_1x_2"},{"type":"note","text":"$x^2 - 5x + 3 = 0$: $x_1^2 + x_2^2 = 25 - 6 = 19$."}]},{"kicker":"Кері есеп","title":"Түбірлер бойынша теңдеу құру","blocks":[{"type":"formula","tex":"x^2 - (x_1 + x_2)x + x_1x_2 = 0"},{"type":"list","items":["Түбірлері $2$ және $-3$: $x^2 + x - 6 = 0$.","Түбірлері берілген теңдеудің түбірлерінен екі есе үлкен теңдеу: қосынды $2$ есе, көбейтінді $4$ есе артады."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Түбірлер қосындысы $-\\frac{b}{a}$ — минус таңбасымен.","$a \\ne 1$ болса, $a$-ға бөлуді ұмытады.","$x_1^2 + x_2^2 \\ne (x_1 + x_2)^2$.","$D < 0$ болса, формулалар «есептесе» де, Виет теоремасы нақты түбірлер бермейді."]}]}]}'::jsonb
