SET content_kk = '{"pages":[{"kicker":"Жұмыс","title":"Күштің механикалық жұмысы","blocks":[{"type":"formula","tex":"A = Fs\\cos\\alpha"},{"type":"list","items":["$\\alpha$ — күш пен орын ауыстыру арасындағы бұрыш.","$\\alpha < 90°$ — жұмыс оң, $\\alpha = 90°$ — нөлге тең, $\\alpha > 90°$ — теріс.","Дене $h$ биіктікке көтерілгенде ауырлық күшінің жұмысы $-mgh$ болады. Қозғалмайтын бетпен сырғанағанда үйкеліс жұмысы теріс.","Центрге тартқыш күш жұмыс атқармайды."]}]},{"kicker":"Жұмыс және график","title":"Айнымалы күш","blocks":[{"type":"list","items":["Жұмыс = $F(x)$ графигінің астындағы аудан.","Серіппені созу: $A = \\frac{kx^2}{2}$ — үшбұрыштың ауданы.","Ауырлық күшінің жұмысы траекторияға тәуелсіз — тек биіктіктер айырымына тәуелді."]}]},{"kicker":"Қуат","title":"Жұмыстың орындалу жылдамдығы","blocks":[{"type":"formula","tex":"N = \\frac{A}{t} = Fv \\qquad [N] = \\text{Вт}"},{"type":"list","items":["$1$ кВт $= 1000$ Вт.","Қозғалтқыштың қуаты тұрақты болғанда тарту күші жылдамдыққа кері пропорционал: $F = \\frac{N}{v}$."]}]},{"kicker":"ПӘК","title":"Пайдалы әрекет коэффициенті","blocks":[{"type":"formula","tex":"\\eta = \\frac{A_{\\text{пайд}}}{A_{\\text{жұмс}}} \\cdot 100\\%"},{"type":"list","items":["ПӘК әрқашан 100%-дан кіші.","Жүкті көлбеу жазықтық бойымен көтеру: пайдалы жұмыс $mgh$, жұмсалған $Fl$."]}]},{"kicker":"ҰБТ қақпандары","title":"Жиі қателесетін жерлер","blocks":[{"type":"trap","items":["Адам жүкті бір орында ұстап тұр — жұмыс нөлге тең (орын ауыстыру жоқ).","Горизонтпен емес, күш пен **орын ауыстыру** арасындағы бұрыш.","Қуат кВт-пен берілсе — Вт-қа аудар.","100%-дан үлкен ПӘК — есептеудегі қатенің белгісі."]}]}]}'::jsonb
